// Writes workers/site/src/render/fonts.ts: the open-licence fonts the website templates use, so a
// site serves them itself and makes no third-party requests. Licences: design/2026-11/fonts/OFL-*.
// Usage: node scripts/build-site-fonts.mjs
import { readFileSync, writeFileSync } from 'node:fs';

const FONTS = {
  grotesk: 'schibsted-grotesk-latin-wght-normal.woff2',
  archivo: 'archivo-latin-standard-normal.woff2',
};
const lines = [
  '// Generated by scripts/build-site-fonts.mjs. Do not edit.',
  'export const SITE_FONTS: Record<string, string> = {',
];
for (const [name, file] of Object.entries(FONTS)) {
  const data = readFileSync(new URL(`../design/2026-11/fonts/${file}`, import.meta.url));
  lines.push(`  ${name}: '${data.toString('base64')}',`);
}
lines.push('};', '');
writeFileSync(new URL('../workers/site/src/render/fonts.ts', import.meta.url), lines.join('\n'));
